// Exposure mirrors urn:alixai:schema:policy:decision-record:v1#/$defs/exposure.
//
// The compact record of one Expose call: for every capability the package declares, whether the
// model may be shown it, in one record instead of one decision record per capability (the audit
// cost of a turn then no longer grows with the size of the catalogue). It names who asked, the
// package and the policies in force (so the record can be tied to the exact signed policy) and one
// outcome per capability. A catalogue too large for one record (at most 256 outcomes and 24 KiB)
// is split over parts, numbered from 1; the parts together list every capability once, and a
// reader that finds fewer than parts records for one call has found an incomplete trail: a call
// that wrote fewer than parts records exposed nothing to the model, whatever the parts that were
// written say, because Expose shows capabilities only once every part is in the log. A
// package-level denial (a quarantined package, a wrong application or tenant) is not an exposure
// record but a decision record. The subject leaves out the token's capability list: a capability
// the token did not permit appears in outcomes as a denial with the reason
// capability_not_in_token_scope.
//
// The schema also states cross-field rules (if/then/else, required alternatives and similar) that
// this type does not express: validate payloads against the schema.
type Exposure struct {
	// The record format and its major version.
	Format string `json:"format"`

	// Core-minted ID of this record (prefix pdec). The decisions Expose returns carry the ID
	// of the record that holds them.
	DecisionID string `json:"decision_id"`

	// When the exposure was decided, from the injected clock.
	DecidedAt common.Timestamp `json:"decided_at"`

	// Always expose: before a tool is shown to the model.
	Phase string `json:"phase"`

	// allow when at least one capability of this record may be shown to the model, deny when
	// none may. The outcome of each capability is in outcomes.
	Outcome ExposureOutcome `json:"outcome"`

	// Present on deny only: permission_denied, there being no capability the model may be
	// shown. Why each capability was denied is in outcomes.
	Code *applicationpackage.ErrorCode `json:"code,omitzero"`

	// The verified context the exposure was decided for, without the token's capability list.
	Subject ExposureSubject `json:"subject"`

	Package PackageRef `json:"package"`

	// The host policies in force, by ID and the SHA-256 of their canonical JSON, so the
	// exposure can be tied to the exact signed policy.
	Policies []PolicyRef `json:"policies"`

	// How many capabilities the Expose call evaluated in all, across every part.
	Considered int64 `json:"considered"`

	// The number of this record among the records of the call, from 1.
	Part int64 `json:"part"`

	// How many records the call wrote.
	Parts int64 `json:"parts"`

	// The capabilities of this part, sorted by capability ID: one entry each, allowed or
	// denied.
	Outcomes []CapabilityOutcome `json:"outcomes"`
}

